const sanitizeString = (str) => {
  return str
    .replace(/[^\w\s]/gi, "")
    .replace(/\s+/g, " ")
    .trim();
};

const items = $input.all();
const sanitizedItems = items.map((item) => {
  const cleanedData = {};
  for (const key in item.json) {
    if (typeof item.json[key] === "string" && key !== "Email ") {
      cleanedData[key] = sanitizeString(item.json[key]);
    } else {
      cleanedData[key] = item.json[key];
    }
  }
  return { json: cleanedData };
});

return sanitizedItems;

